\set ON_ERROR_STOP on
begin;
create temporary table operational_scope_fixture(data jsonb not null);
insert into operational_scope_fixture values(:'fixture'::jsonb);
create function pg_temp.scope_assert(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'scope assertion failed: %',label;end if;end;$$;
create function pg_temp.scope_fail_ownership() returns trigger language plpgsql as $$begin raise exception 'synthetic scope ownership failure' using errcode='22023';end;$$;
do $$
declare f jsonb;preview jsonb;command jsonb;receipt jsonb;first_receipt jsonb;bad jsonb;v_scope uuid:='10101010-1010-4010-8010-101010101010';v_alt uuid:='20202020-2020-4020-8020-202020202020';
begin
 select data into strict f from operational_scope_fixture;
 insert into public.operations_project_scope_packing_policies values('11111111-1111-4111-8111-111111111111','delivered',true);
 perform set_config('request.jwt.claims','{"sub":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","role":"authenticated"}',true);execute 'set local role authenticated';
 preview:=public.preview_operations_project_scope_v1('large_project','cccccccc-cccc-4ccc-8ccc-cccccccccccc');
 perform pg_temp.scope_assert(preview->'membership'=f->'initial' and preview->>'membership_raw'=f->>'initialRaw' and preview->>'membership_fingerprint'=f->>'initialHash','JS/native SQL canonical membership parity including exact legacy text IDs');
 preview:=public.preview_operations_project_scope_v1('packing_project','eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee');perform pg_temp.scope_assert(preview->'membership'=f->'packing' and preview->>'membership_fingerprint'=f->>'packingHash','packing parent join identity parity');
 preview:=public.preview_operations_project_scope_v1('project','55555555-5555-4555-8555-555555555555');perform pg_temp.scope_assert(preview->'membership'=f->'project' and preview->>'membership_fingerprint'=f->>'projectHash','project shared-booking leaves retained once');
 execute 'reset role';update public.operations_project_scope_packing_policies set enabled=false;execute 'set local role authenticated';
 begin perform public.preview_operations_project_scope_v1('packing_project','eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee');raise exception 'disabled packing policy allowed';exception when insufficient_privilege then if sqlerrm<>'scope_packing_missing_or_unenrolled' then raise;end if;end;
 execute 'reset role';update public.operations_project_scope_packing_policies set enabled=true;
 update public.projects set organization_id='88888888-8888-4888-8888-888888888888' where id='55555555-5555-4555-8555-555555555555';execute 'set local role authenticated';
 begin perform public.preview_operations_project_scope_v1('large_project','cccccccc-cccc-4ccc-8ccc-cccccccccccc');raise exception 'foreign source leaf accepted';exception when insufficient_privilege then if sqlerrm<>'scope_project_leaf_foreign' then raise;end if;end;
 execute 'reset role';update public.projects set organization_id='11111111-1111-4111-8111-111111111111' where id='55555555-5555-4555-8555-555555555555';
 insert into public.bookings values('Unmapped-Mirror','11111111-1111-4111-8111-111111111111','cccccccc-cccc-4ccc-8ccc-cccccccccccc');execute 'set local role authenticated';
 begin perform public.preview_operations_project_scope_v1('large_project','cccccccc-cccc-4ccc-8ccc-cccccccccccc');raise exception 'mirror fallback became membership';exception when sqlstate '22023' then if sqlerrm<>'scope_legacy_mirror_without_master' then raise;end if;end;
 execute 'reset role';delete from public.bookings where id='Unmapped-Mirror';
 insert into public.large_projects values('dddddddd-dddd-4ddd-8ddd-dddddddddddd','11111111-1111-4111-8111-111111111111',null,null);
 insert into public.large_project_bookings values('89898989-8989-4898-8898-898989898989','11111111-1111-4111-8111-111111111111','dddddddd-dddd-4ddd-8ddd-dddddddddddd','Legacy-Order-42');execute 'set local role authenticated';
 begin perform public.preview_operations_project_scope_v1('project','55555555-5555-4555-8555-555555555555');raise exception 'multiple live MASTER parents accepted';exception when sqlstate '22023' then if sqlerrm<>'scope_ambiguous_live_large_parents' then raise;end if;end;
 execute 'reset role';update public.large_projects set deleted_at=now() where id='dddddddd-dddd-4ddd-8ddd-dddddddddddd';execute 'set local role authenticated';
 preview:=public.preview_operations_project_scope_v1('project','55555555-5555-4555-8555-555555555555');perform pg_temp.scope_assert(preview->>'membership_fingerprint'=f->>'projectHash','deleted historical MASTER does not compete');execute 'reset role';
 update public.large_projects set deleted_at=now() where id='cccccccc-cccc-4ccc-8ccc-cccccccccccc';execute 'set local role authenticated';
 begin perform public.preview_operations_project_scope_v1('packing_project','eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee');raise exception 'deleted packing parent accepted';exception when insufficient_privilege then if sqlerrm<>'scope_packing_parent_unavailable' then raise;end if;end;
 execute 'reset role';update public.large_projects set deleted_at=null where id='cccccccc-cccc-4ccc-8ccc-cccccccccccc';execute 'set local role authenticated';
 command:=jsonb_build_object('schema','operations-project-scope-enroll.v1','economic_scope_id',v_scope,'root_kind','large_project','root_id','CCCCCCCC-CCCC-4CCC-8CCC-CCCCCCCCCCCC','expected_revision',0,'expected_membership_fingerprint',f->>'initialHash','idempotency_key','synthetic-scope-initial','reason','Reviewed complete membership without assigning a budget');
 foreach bad in array array[command||'{"actor_id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa"}',command||'{"organization_id":"11111111-1111-4111-8111-111111111111"}',command||'{"expected_revision":"0"}',command||'{"expected_revision":0.5}',command||'{"expected_revision":9007199254740991}',command||'{"reason":null}',command||jsonb_build_object('reason',E'\tUnreviewed whitespace'),command||'{"expected_membership_fingerprint":["invalid"]}'] loop
  begin perform public.enroll_operations_project_scope_v1(bad);raise exception 'malformed scope intent accepted';exception when sqlstate '22023' then if sqlerrm<>'invalid_project_scope_enrollment' then raise;end if;end;
 end loop;
 begin perform public.enroll_operations_project_scope_v1(command||'{"expected_revision":1}');raise exception 'new scope wrong CAS accepted';exception when unique_violation then if sqlerrm<>'scope_revision_conflict' then raise;end if;end;
 execute 'reset role';perform pg_temp.scope_assert(not exists(select 1 from public.operations_project_scope_heads),'new stale CAS has no ghost head');execute 'set local role authenticated';
 begin perform public.enroll_operations_project_scope_v1(command||jsonb_build_object('expected_membership_fingerprint',repeat('f',64)));raise exception 'stale preview accepted';exception when sqlstate '22023' then if sqlerrm<>'scope_membership_preview_changed' then raise;end if;end;
 execute 'reset role';execute 'create trigger synthetic_scope_rollback before insert on public.operations_project_scope_member_ownership for each row execute function pg_temp.scope_fail_ownership()';execute 'set local role authenticated';
 begin perform public.enroll_operations_project_scope_v1(command);raise exception 'injected ownership failure did not rollback';exception when sqlstate '22023' then if sqlerrm<>'synthetic scope ownership failure' then raise;end if;end;
 execute 'reset role';perform pg_temp.scope_assert(not exists(select 1 from public.operations_project_scope_heads) and not exists(select 1 from public.operations_project_scope_snapshots),'head snapshot and ownership atomic rollback');execute 'drop trigger synthetic_scope_rollback on public.operations_project_scope_member_ownership';execute 'set local role authenticated';
 first_receipt:=public.enroll_operations_project_scope_v1(command);perform pg_temp.scope_assert(first_receipt->>'outcome'='accepted' and first_receipt->>'scope_revision'='1' and first_receipt->'shadow_only'='true','first shadow accepted');
 receipt:=public.enroll_operations_project_scope_v1(command);perform pg_temp.scope_assert(receipt->>'outcome'='replayed' and receipt->>'snapshot_id'=first_receipt->>'snapshot_id','immutable exact retry');
 begin perform public.enroll_operations_project_scope_v1(command||'{"reason":"Changed reason"}');raise exception 'changed same-key accepted';exception when unique_violation then if sqlerrm<>'scope_idempotency_conflict' then raise;end if;end;
 begin perform public.enroll_operations_project_scope_v1(command||jsonb_build_object('economic_scope_id',v_alt,'root_kind','project','root_id','55555555-5555-4555-8555-555555555555','expected_membership_fingerprint',f->>'projectHash','idempotency_key','synthetic-scope-owner-conflict'));raise exception 'second source project/booking owner accepted';exception when unique_violation then if sqlerrm<>'scope_member_already_owned' then raise;end if;end;
 execute 'reset role';perform pg_temp.scope_assert((select count(*) from public.operations_project_scope_member_ownership)=3,'two project leaves one local booking reserved once');
 insert into public.bookings values('Added-Order-9','11111111-1111-4111-8111-111111111111',null);insert into public.large_project_bookings values('23232323-2323-4232-8232-232323232323','11111111-1111-4111-8111-111111111111','cccccccc-cccc-4ccc-8ccc-cccccccccccc','Added-Order-9');execute 'set local role authenticated';
 preview:=public.preview_operations_project_scope_v1('large_project','cccccccc-cccc-4ccc-8ccc-cccccccccccc');perform pg_temp.scope_assert(preview->'membership'=f->'added' and preview->>'membership_fingerprint'=f->>'addedHash','new relationship invalidates old preview');
 receipt:=public.enroll_operations_project_scope_v1(command);perform pg_temp.scope_assert(receipt->>'snapshot_id'=first_receipt->>'snapshot_id','historical exact retry retains original source capture');
 begin perform public.enroll_operations_project_scope_v1(command||'{"expected_revision":1,"idempotency_key":"synthetic-scope-stale-preview"}');raise exception 'changed graph old preview accepted';exception when sqlstate '22023' then if sqlerrm<>'scope_membership_preview_changed' then raise;end if;end;
 receipt:=public.enroll_operations_project_scope_v1(command||jsonb_build_object('expected_revision',1,'expected_membership_fingerprint',f->>'addedHash','idempotency_key','synthetic-scope-added'));perform pg_temp.scope_assert(receipt->>'scope_revision'='2','complete membership revision advances');
 execute 'reset role';perform pg_temp.scope_assert((select membership from public.operations_project_scope_snapshots where scope_revision=1)=f->'initial','original snapshot retained unchanged');
 insert into public.bookings values(U&'\E000','11111111-1111-4111-8111-111111111111',null),(U&'\+010000','11111111-1111-4111-8111-111111111111',null);
 insert into public.large_project_bookings values('56565656-5656-4565-8565-565656565656','11111111-1111-4111-8111-111111111111','cccccccc-cccc-4ccc-8ccc-cccccccccccc',U&'\E000'),('67676767-6767-4676-8676-676767676767','11111111-1111-4111-8111-111111111111','cccccccc-cccc-4ccc-8ccc-cccccccccccc',U&'\+010000');
 execute 'set local role authenticated';preview:=public.preview_operations_project_scope_v1('large_project','cccccccc-cccc-4ccc-8ccc-cccccccccccc');
 perform pg_temp.scope_assert(preview->'membership'=f->'unicode' and preview->>'membership_raw'=f->>'unicodeRaw' and preview->>'membership_fingerprint'=f->>'unicodeHash','UTF8 byte-order/raw/hash native parity for BMP and supplementary local text IDs');execute 'reset role';
 delete from public.large_project_bookings where id in('56565656-5656-4565-8565-565656565656','67676767-6767-4676-8676-676767676767');delete from public.bookings where id in(U&'\E000',U&'\+010000');
 -- Duplicate relevant MASTER rows must fail for all root kinds.
 insert into public.large_project_bookings values('34343434-3434-4343-8343-343434343434','11111111-1111-4111-8111-111111111111','cccccccc-cccc-4ccc-8ccc-cccccccccccc','Legacy-Order-42');execute 'set local role authenticated';
 begin perform public.preview_operations_project_scope_v1('project','55555555-5555-4555-8555-555555555555');raise exception 'duplicate MASTER accepted for project';exception when sqlstate '22023' then if sqlerrm<>'duplicate_scope_relationship' then raise;end if;end;
 begin perform public.preview_operations_project_scope_v1('packing_project','eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee');raise exception 'duplicate MASTER accepted for packing';exception when sqlstate '22023' then if sqlerrm<>'duplicate_scope_relationship' then raise;end if;end;
 execute 'reset role';delete from public.large_project_bookings where id='34343434-3434-4343-8343-343434343434';
 -- Parent edge identity, not just its endpoint, is captured.
 update public.large_project_bookings set id='45454545-4545-4454-8454-454545454545' where id='ffffffff-ffff-4fff-8fff-ffffffffffff';execute 'set local role authenticated';preview:=public.preview_operations_project_scope_v1('packing_project','eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee');perform pg_temp.scope_assert(preview->>'membership_fingerprint'<>f->>'packingHash','reinserted parent identity changes packing proof');execute 'reset role';
 delete from public.large_project_bookings where large_project_id='cccccccc-cccc-4ccc-8ccc-cccccccccccc';update public.large_projects set primary_booking_id=null where id='cccccccc-cccc-4ccc-8ccc-cccccccccccc';execute 'set local role authenticated';
 preview:=public.preview_operations_project_scope_v1('large_project','cccccccc-cccc-4ccc-8ccc-cccccccccccc');perform pg_temp.scope_assert(preview->'membership'=f->'empty' and preview->>'membership_fingerprint'=f->>'emptyHash','empty complete membership snapshot does not fabricate source leaves');
 receipt:=public.enroll_operations_project_scope_v1(command||jsonb_build_object('expected_revision',2,'expected_membership_fingerprint',f->>'emptyHash','idempotency_key','synthetic-scope-empty'));perform pg_temp.scope_assert(receipt->>'scope_revision'='3','empty complete replacement advances');
 preview:=public.preview_operations_project_scope_v1('project','55555555-5555-4555-8555-555555555555');
 begin perform public.enroll_operations_project_scope_v1(command||jsonb_build_object('economic_scope_id',v_alt,'root_kind','project','root_id','55555555-5555-4555-8555-555555555555','expected_membership_fingerprint',preview->>'membership_fingerprint','idempotency_key','synthetic-scope-transfer-after-removal'));raise exception 'removed member silently transferred';exception when unique_violation then if sqlerrm<>'scope_member_already_owned' then raise;end if;end;execute 'reset role';
 -- No authenticated direct evidence access, no forged service identity.
 execute 'set local role authenticated';begin perform 1 from public.operations_project_scope_snapshots;raise exception 'direct client evidence access allowed';exception when insufficient_privilege then null;end;execute 'reset role';
 perform set_config('request.jwt.claims','{"sub":"bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb","role":"authenticated"}',true);execute 'set local role authenticated';begin perform public.preview_operations_project_scope_v1('large_project','cccccccc-cccc-4ccc-8ccc-cccccccccccc');raise exception 'project user obtained whole scope';exception when insufficient_privilege then if sqlerrm<>'organization_scope_admin_required' then raise;end if;end;execute 'reset role';
 perform set_config('request.jwt.claims','{"sub":"cccccccc-cccc-4ccc-8ccc-cccccccccccc","role":"authenticated"}',true);execute 'set local role authenticated';begin perform public.preview_operations_project_scope_v1('large_project','cccccccc-cccc-4ccc-8ccc-cccccccccccc');raise exception 'foreign admin scope access';exception when insufficient_privilege then if sqlerrm<>'scope_root_missing_or_foreign' then raise;end if;end;execute 'reset role';
 perform set_config('request.jwt.claims','{"sub":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","role":"authenticated"}',true);delete from public.user_roles where user_id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa' and role='admin';execute 'set local role authenticated';begin perform public.enroll_operations_project_scope_v1(command);raise exception 'revoked admin replay allowed';exception when insufficient_privilege then if sqlerrm<>'organization_scope_admin_required' then raise;end if;end;execute 'reset role';
 begin update public.operations_project_scope_snapshots set reason='rewrite';raise exception 'immutable snapshot rewritten';exception when sqlstate '55000' then null;end;
 begin delete from public.operations_project_scope_member_ownership;raise exception 'ownership silently released';exception when sqlstate '55000' then null;end;
 begin update public.operations_project_scope_heads set current_revision=0;raise exception 'saved head rewound';exception when sqlstate '55000' then if sqlerrm<>'scope_saved_head_required' then raise;end if;end;
 begin execute 'truncate public.operations_project_scope_snapshots cascade';raise exception 'snapshot truncated';exception when sqlstate '55000' then null;end;
 begin execute 'truncate public.operations_project_scope_heads cascade';raise exception 'head truncated';exception when sqlstate '55000' then if sqlerrm<>'scope_head_cannot_be_removed' then raise;end if;end;
end;$$;
rollback;
select 'operations-canonical-scope-postgres PASS' as result;
